def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    opp_pressures = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                pressure = float(bid)
                if opp.get('no_water_days', 0) >= 1:
                    pressure += 8.0
                if opp.get('hp', 10) <= 4:
                    pressure += 10.0
                if opp.get('budget', 0) < 40:
                    pressure -= 6.0
                opp_pressures.append(pressure)

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strongest_pressure = max(opp_pressures) if opp_pressures else highest_prev

    scarcity = (float(MAX_SUPPLY) - float(supply)) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water >= 2:
        urgency += 1.0
    elif no_water >= 1:
        urgency += 0.45

    base = 20.0 + 18.0 * scarcity

    if urgency >= 1.4:
        bid = max(62.0, strongest_pressure + 2.5, base + 25.0)
    elif urgency >= 0.7:
        bid = max(45.0, highest_prev + 1.5, base + 12.0)
    else:
        if supply >= 22:
            bid = max(18.0, min(34.0, highest_prev * 0.55 + 4.0))
        elif supply >= 19:
            bid = max(26.0, min(46.0, highest_prev * 0.72 + 3.0))
        else:
            bid = max(34.0, min(58.0, highest_prev * 0.82 + 4.0))

    if day >= 8:
        bid += 6.0 * urgency + 4.0 * scarcity

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.92)
    else:
        reserve_target = max(0.0, (10 - day) * 18.0)
        if budget - bid < reserve_target and urgency < 1.0:
            bid = max(15.0, budget - reserve_target)

    if hp >= 7 and no_water == 0 and supply >= 23 and highest_prev >= 90:
        bid = min(bid, 22.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    highest_prev = max(yesterday_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if supply < 18:
        return min(my_status['budget'], highest_prev + 5.0)

    return min(my_status['budget'], max(DAILY_SALARY * 0.4, highest_prev * 0.9))
